package com.bank.onboarding;

import java.util.*;
import java.util.logging.*;

public class ConstructorRefDemo {
    private static final Logger log = Logger.getLogger("Onboarding");
    static {
        ConsoleHandler h = new ConsoleHandler();
        h.setFormatter(new SimpleFormatter());
        log.setUseParentHandlers(false);
        log.addHandler(h);
    }

    public static void main(String[] args) {
        List<String> rawNames = List.of("Rajesh", "Priya", "Amit");
        OnboardingService service = new OnboardingService();

        List<Employee> employees = service.fromNames(rawNames);
        employees.forEach(e -> log.info(() -> "created: " + e.getName()));
    }
}

// ─── Would be in model/Employee.java ───
class Employee {
    private final String name;
    Employee(String name) { this.name = name; }   // constructor matched by Employee::new
    String getName() { return name; }
}

// ─── Would be in service/OnboardingService.java ───
class OnboardingService {
    List<Employee> fromNames(List<String> names) {
        return names.stream()
            .map(Employee::new)     // String → Employee (Function<String, Employee>)
            .toList();
    }
}
